<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {useAuthStore} from '../../stores/auth'
import type {PortfolioAnalysis} from '../../api/portfolioAnalyses'
import {ApiError} from '../../api/auth'
import * as api from '../../api/portfolioQuestions'
const props=defineProps<{analysis:PortfolioAnalysis;currentBookRevision:string|null}>()
const auth=useAuthStore(),owner=computed(()=>auth.profile?.userId||'')
const question=ref(''),disclosure=ref(false),configured=ref(false),initializing=ref(false),busy=ref(false),reading=ref(false),ruleBusy=ref(false),historyBusy=ref(false)
const storageBlocked=ref(false),missingOperation=ref(false),frozenQuestion=ref(''),knownInputRejection=ref(false)
const error=ref(''),rule=ref<api.PortfolioRule|null>(null),answer=ref<api.QuestionAnswer|null>(null),history=ref<api.QuestionAnswer[]>([]),operation=ref<api.QuestionReceipt|null>(null),requestId=ref<string|null>(null),upper=ref<string|null>(null),nextBefore=ref<string|null>(null)
let epoch=0,answerSequence=0,ruleSequence=0,historySequence=0
const count=computed(()=>[...question.value.normalize('NFC').trim()].length)
const inputError=computed(()=>{if(/[\u0000-\u001f\u007f-\u009f]/u.test(question.value)||/[\uD800-\uDFFF]/u.test(question.value))return '问题不能包含换行或控制字符，请改成一段后再发送。';if(/\b(?:api[_ -]?key|authorization|smtp[_ -]?(?:password|token)|password)\s*[:=]|\bBearer\s+\S+|\bsk-[A-Za-z0-9_-]{16,}/i.test(question.value))return '请移除密码或密钥，不要将凭据发送给AI。';return ''})
const pending=computed(()=>!!requestId.value&&(!operation.value||operation.value.state==='RUNNING'))
const canSend=computed(()=>!!owner.value&&configured.value&&props.analysis.valuedCount>0&&disclosure.value&&count.value>0&&count.value<=300&&!inputError.value&&!busy.value&&!initializing.value&&!reading.value&&!pending.value&&!storageBlocked.value)
const ruleChoices:[api.RuleTopic,string][]=[['PROFIT_FORMULA','盈亏怎么计算'],['RETURN_LIMIT','为什么收益率无法计算'],['COVERAGE_LIMIT','为什么只展示部分合计'],['CONCENTRATION_RULE','如何理解持仓占比']]
const visibleRuleChoices=computed(()=>ruleChoices.filter(([topic])=>topic==='RETURN_LIMIT'?props.analysis.valuedCount===0||props.analysis.lines.some(l=>l.returnPercent===null):topic==='COVERAGE_LIMIT'?props.analysis.state!=='COMPLETE'||props.analysis.mixedDates:true))
const canRestore=computed(()=>!!owner.value&&configured.value&&missingOperation.value&&!!requestId.value&&disclosure.value&&count.value>0&&count.value<=300&&!inputError.value&&!busy.value&&!initializing.value&&!storageBlocked.value)
const quickQuestions=['哪些持仓比较集中？','这份估值需要注意什么？','这份持仓的盈亏应该怎么理解？']
const storageKey=(id:string,analysisId:string)=>'aistock:portfolio-question:'+id+':'+analysisId
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
function message(e:unknown){return e instanceof Error?e.message:'问答操作未完成，请先查询原请求。'}
function validAccount(e:number){return e===epoch&&!!owner.value}
function stored(){try{const value=sessionStorage.getItem(storageKey(owner.value,props.analysis.analysisId));if(!value)return null;const n=JSON.parse(value) as {operationId?:string;analysisId?:string};if(n.analysisId!==props.analysis.analysisId||!n.operationId||!uuid.test(n.operationId))throw new Error('原请求恢复信息不完整');return n.operationId}catch(e){storageBlocked.value=true;error.value='无法读取原请求恢复信息，请勿重复发送。'+message(e);return null}}
function remember(id:string){try{sessionStorage.setItem(storageKey(owner.value,props.analysis.analysisId),JSON.stringify({operationId:id,analysisId:props.analysis.analysisId}));return true}catch{error.value='无法保存原请求恢复信息，本次未发送，请启用本机存储后再试。';return false}}
async function loadAnswer(id:string,e=epoch){if(!validAccount(e))return;const seq=++answerSequence;reading.value=true;try{const result=await api.getQuestionAnswer(id);if(!validAccount(e)||seq!==answerSequence)return;if(result.analysisId!==props.analysis.analysisId||result.context.sourceAnalysisId!==props.analysis.analysisId||(props.analysis.sourceHash&&result.context.sourceHash!==props.analysis.sourceHash))throw new ApiError('INVALID_RESPONSE','回答依据与当前估值不一致，未展示该回答',422);answer.value=result}catch(x){if(validAccount(e)&&seq===answerSequence)error.value=message(x)}finally{if(validAccount(e)&&seq===answerSequence)reading.value=false}}
async function loadHistory(more=false,e=epoch){if(!validAccount(e))return;const seq=++historySequence;historyBusy.value=true;try{const result=await api.listQuestions(props.analysis.analysisId,more?nextBefore.value??undefined:undefined,more?upper.value??undefined:undefined);if(!validAccount(e)||seq!==historySequence)return;if(result.items.some(a=>a.analysisId!==props.analysis.analysisId))throw new ApiError('INVALID_RESPONSE','问答记录归属不一致',422);history.value=more?[...history.value,...result.items]:result.items;configured.value=result.configured;upper.value=result.upper;nextBefore.value=result.nextBefore;if(!requestId.value&&result.latestAttempt){requestId.value=result.latestAttempt.operationId;await accept(result.latestAttempt,e)}}catch(x){if(validAccount(e)&&seq===historySequence)error.value=message(x)}finally{if(validAccount(e)&&seq===historySequence)historyBusy.value=false}}
function failureMessage(code:string|null){
 const reason=code==='AI_TIMEOUT'?'AI回答等待超时，本次已结束，未自动重试。':code==='AI_CONNECTION_FAILED'?'暂时无法连接AI服务，本次已结束，未自动重试。':code==='AI_INTERRUPTED'?'本次AI回答已中断，未自动重试。':'上次回答未完成。'
 return reason+'原估值和已有回答保留。原因：'+(code||'AI_UNAVAILABLE')
}
async function accept(result:api.QuestionReceipt,e:number){if(!validAccount(e))return;if(result.analysisId!==props.analysis.analysisId||result.operationId!==requestId.value)throw new ApiError('INVALID_RESPONSE','原请求与当前估值不一致',422);operation.value=result;missingOperation.value=false;frozenQuestion.value=result.question;if(result.state==='SUCCEEDED'&&result.answerId){error.value='';await loadAnswer(result.answerId,e)}else if(result.state==='FAILED'){error.value=failureMessage(result.errorCode)}}
async function recover(e=epoch){if(!validAccount(e)||!requestId.value)return;try{const result=await api.getQuestionOperation(requestId.value);if(!validAccount(e))return;question.value=result.question;await accept(result,e)}catch(x){if(validAccount(e)){missingOperation.value=x instanceof ApiError&&x.status===404;if(missingOperation.value&&knownInputRejection.value){try{sessionStorage.removeItem(storageKey(owner.value,props.analysis.analysisId));requestId.value=null;operation.value=null;frozenQuestion.value='';missingOperation.value=false;knownInputRejection.value=false;error.value='问题已被服务端拒绝，且未创建问答记录。请修改问题后再发送。'}catch{storageBlocked.value=true;error.value='无法清理原请求恢复信息，请先恢复本机存储，本次不再发送。'}}else error.value='原请求状态暂未确认，请查询原请求，不要重复发送。'+message(x)}}}
async function queryOperation(){if(busy.value)return;const e=epoch;busy.value=true;try{await recover(e)}finally{if(validAccount(e))busy.value=false}}
async function send(){if(!canSend.value)return;const e=epoch,id=crypto.randomUUID(),text=question.value.normalize('NFC').trim();if(!remember(id))return;requestId.value=id;operation.value=null;missingOperation.value=false;frozenQuestion.value=text;knownInputRejection.value=false;error.value='';busy.value=true;try{const result=await api.createQuestion({operationId:id,analysisId:props.analysis.analysisId,question:text,disclosureAccepted:true});if(!validAccount(e))return;await accept(result,e);await loadHistory(false,e)}catch(x){if(!validAccount(e))return;knownInputRejection.value=x instanceof ApiError&&x.status===400&&x.code==='AI_REQUEST_INVALID';error.value=message(x);await recover(e)}finally{if(validAccount(e))busy.value=false}}
async function restoreOriginal(){if(!canRestore.value||!requestId.value)return;const e=epoch,id=requestId.value,text=frozenQuestion.value||question.value.normalize('NFC').trim();knownInputRejection.value=false;busy.value=true;try{const result=await api.createQuestion({operationId:id,analysisId:props.analysis.analysisId,question:text,disclosureAccepted:true});if(validAccount(e)){await accept(result,e);await loadHistory(false,e)}}catch(x){if(validAccount(e)){knownInputRejection.value=x instanceof ApiError&&x.status===400&&x.code==='AI_REQUEST_INVALID';error.value=message(x);await recover(e)}}finally{if(validAccount(e))busy.value=false}}
async function showRule(topic:api.RuleTopic){const e=epoch,seq=++ruleSequence;ruleBusy.value=true;try{const result=await api.getPortfolioRule(props.analysis.analysisId,topic);if(!validAccount(e)||seq!==ruleSequence)return;if(result.analysisId!==props.analysis.analysisId)throw new ApiError('INVALID_RESPONSE','规则依据与所选估值不一致',422);rule.value=result}catch(x){if(validAccount(e)&&seq===ruleSequence)error.value=message(x)}finally{if(validAccount(e)&&seq===ruleSequence)ruleBusy.value=false}}
async function initialize(e:number){initializing.value=true;try{requestId.value=stored();await loadHistory(false,e);if(validAccount(e)&&requestId.value)await recover(e)}finally{if(validAccount(e))initializing.value=false}}
watch(()=>[owner.value,props.analysis.analysisId],()=>{epoch++;answerSequence++;ruleSequence++;historySequence++;question.value='';disclosure.value=false;configured.value=false;error.value='';rule.value=null;answer.value=null;history.value=[];operation.value=null;requestId.value=null;upper.value=null;nextBefore.value=null;busy.value=false;reading.value=false;ruleBusy.value=false;historyBusy.value=false;initializing.value=false;storageBlocked.value=false;missingOperation.value=false;frozenQuestion.value='';knownInputRejection.value=false;if(owner.value)void initialize(epoch)},{immediate:true})
onUnmounted(()=>{epoch++;answerSequence++;ruleSequence++;historySequence++})
</script>
<template>
<section class="portfolio-question" aria-labelledby="portfolio-question-title">
 <h3 id="portfolio-question-title">读懂这份持仓估值</h3>
 <p class="hint">依据保存于 {{analysis.createdAt}} 的估值，截止日 {{analysis.asOfDate}}。实际价格日期以估值各行为准，回答不会自动变成最新行情。</p>
 <p v-if="currentBookRevision===null" class="notice">暂无法核对当前持仓版本。</p><p v-else-if="currentBookRevision!==analysis.bookRevision" class="notice">持仓已修改，这里的说明仍基于所选旧估值。</p>
 <p v-if="analysis.state==='PARTIAL'||analysis.mixedDates" class="notice">{{analysis.mixedDates?'价格来自不同交易日。':''}}仅能解释可估值部分，不能据此计算完整同日组合的占比或集中度。</p>
 <p v-if="analysis.freshness!=='FRESH'" class="notice">{{analysis.freshness==='STALE'?'存在旧行情价格。':'无法确认行情是否覆盖最新预期交易日。'}}不能将此估值称为当前市值。</p>
 <h4>规则说明 <span class="hint">不调用AI</span></h4>
 <div class="choices"><button v-for="[topic,label] in visibleRuleChoices" :key="topic" :data-test="'pq-rule-'+topic" :disabled="ruleBusy||!owner" @click="showRule(topic)">{{label}}</button></div>
 <article v-if="rule" class="answer-block"><strong>规则说明</strong><p>{{rule.text}}</p><ul><li v-for="limit in rule.limits" :key="limit">{{limit}}</li></ul></article>
 <h4>询问AI</h4>
 <p v-if="!configured&&!initializing" role="status">持仓AI问答尚未启用，仍可查看规则说明与已有回答。</p><p v-if="analysis.valuedCount===0" role="status">这份估值没有可分析金额，请先查看规则说明。</p>
 <div class="choices"><button v-for="text in quickQuestions" :key="text" data-test="pq-quick" :disabled="busy||pending" @click="question=text">{{text}}</button></div>
 <label for="portfolio-question-input">你的问题</label><textarea id="portfolio-question-input" v-model="question" data-test="pq-input" rows="3" :disabled="busy||(pending&&(!missingOperation||!!frozenQuestion))" aria-describedby="portfolio-question-help portfolio-question-input-error" :aria-invalid="!!inputError" />
 <p v-if="inputError" id="portfolio-question-input-error" role="alert" class="notice">{{inputError}}</p>
 <p id="portfolio-question-help" class="hint">每次独立回答，仅使用所选估值。请勿填写邮箱、密码或密钥。{{count}} / 300字</p>
 <label class="disclosure"><input v-model="disclosure" data-test="pq-disclosure" type="checkbox" :disabled="busy" /><span>我确认将本次问题及股票、持仓金额、收益率、占比和日期发送至华为云模型用于解释。不发送原始数量、平均成本或账号身份；金额仍是私人信息，也可能被推算。</span></label>
 <div class="actions"><button class="primary" data-test="pq-ask" :disabled="!canSend" @click="send">{{busy?'正在处理…':'发送问题'}}</button><button v-if="requestId" :disabled="busy||initializing" @click="queryOperation">查询原请求状态</button></div>
 <p v-if="missingOperation" class="notice">原请求暂未查到。可填写原问题并确认告知后恢复同一请求；恢复不会更换编号。</p><button v-if="missingOperation" data-test="pq-restore" :disabled="!canRestore" @click="restoreOriginal">恢复原请求</button>
 <p v-if="pending" role="status">原请求状态尚未确认，请先查询；刷新不会重新发送问题。</p><p v-if="initializing||reading" role="status">正在读取已保存问答…</p><p v-if="error" role="alert" class="notice">{{error}}</p>
 <article v-if="answer" class="answer-block"><strong>AI回答</strong><p class="asked">{{answer.question}}</p><p v-if="answer.status==='OUT_OF_SCOPE'">当前保存的估值不足以回答这个问题，可询问盈亏口径、持仓占比或数据限制。</p><p v-for="(part,i) in answer.paragraphs" :key="i">{{part.text}}</p><div class="hint"><p v-for="key in ['COVERAGE_LIMIT','DATE_LIMIT','FRESHNESS_LIMIT','BASIS_LIMIT']" :key="key">{{answer.context.facts[key]}}</p></div><details><summary>查看回答依据</summary><p>估值截止 {{answer.context.facts.AS_OF}} · 回答保存于 {{answer.createdAt}}</p><p>依据估值 {{answer.analysisId}} · {{answer.context.promptVersion}} · {{answer.context.providerModel}}</p><dl><template v-for="key in [...new Set(answer.paragraphs.flatMap(p=>p.refs))]" :key="key"><dt>{{key}}</dt><dd>{{answer.context.facts[key]}}</dd></template></dl></details></article>
 <div class="actions"><h4>这份估值的问答记录</h4><button :disabled="historyBusy||busy" @click="loadHistory(false)">刷新回答记录</button></div><p v-if="!history.length&&!historyBusy" class="hint">还没有这份估值的问答记录。</p><ul class="history"><li v-for="item in history" :key="item.answerId"><button data-test="pq-history" :disabled="reading||busy" @click="loadAnswer(item.answerId)">{{item.question}} · {{item.createdAt}}</button></li></ul><button v-if="nextBefore" :disabled="historyBusy||busy" @click="loadHistory(true)">加载更多</button>
</section>
</template>
<style scoped>
.portfolio-question{border-top:1px solid var(--border);margin-top:24px;padding-top:20px;line-height:1.7;overflow-wrap:anywhere}.choices,.actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:12px 0}.hint{color:var(--muted,#52647c);font-size:14px}.notice{padding:12px;border-left:3px solid #9b6216;background:#fff8e9;color:#69420e}.disclosure{display:flex;align-items:flex-start;gap:12px;margin:16px 0;font-size:14px}.disclosure input{width:20px;height:20px;flex-shrink:0;margin-top:4px}textarea{display:block;width:100%;box-sizing:border-box;margin-top:8px;padding:12px;border:1px solid var(--border);border-radius:8px;background:var(--surface,#fff);color:var(--ink);font:inherit;resize:vertical}button{min-height:44px;padding:9px 14px;background:var(--surface,#fff);border:1px solid var(--border);border-radius:8px;color:var(--ink);font:inherit;cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}button.primary{background:var(--primary,#285ad6);color:#fff}button:focus-visible,textarea:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--primary,#285ad6);outline-offset:3px}.answer-block{border:1px solid var(--border);padding:16px;border-radius:10px;margin:16px 0}.asked{font-weight:600}.history{list-style:none;padding:0;display:grid;gap:10px}.history button{max-width:100%;text-align:left;overflow-wrap:anywhere}summary{min-height:44px;cursor:pointer;align-content:center}dd{margin:0 0 10px}h4{margin:16px 0 8px}@media(max-width:500px){.choices button,.actions .primary{width:100%}.answer-block{padding:12px}}
</style>
